"""Independent post-run reconstruction; no diagnostic script imports."""
from pathlib import Path
import gzip, hashlib, json
import torch
from attcon.bound_content import VisualEncoder

ROOT=Path('audits/isolated_orientation_task_v1')
MAX_DIFF={}
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def same(a,b,path=''):
    if isinstance(a,torch.Tensor):
        assert a.dtype==b.dtype and a.shape==b.shape,path
        if a.is_floating_point():
            diff=float((a-b).abs().max()) if a.numel() else 0
            MAX_DIFF[path]=diff
            assert torch.allclose(a,b,atol=1e-12,rtol=1e-12), (path,diff)
        else:assert torch.equal(a,b),path
    elif isinstance(a,dict):
        assert a.keys()==b.keys(),path
        for k in a:same(a[k],b[k],path+'/'+str(k))
    elif isinstance(a,(list,tuple)):
        assert len(a)==len(b),path
        for k,(x,y) in enumerate(zip(a,b)):same(x,y,path+'/'+str(k))
    elif isinstance(a,float):assert abs(a-b)<=1e-12,(path,a,b)
    else:assert a==b,(path,a,b)

def images(seed,n):
    rng=torch.Generator().manual_seed(seed)
    y=(torch.arange(n)%2)[torch.randperm(n,generator=torch.Generator().manual_seed(seed+1000000))]
    v,h=torch.meshgrid(torch.arange(16),torch.arange(16),indexing='ij')
    x0=7.5+2*torch.rand(n,1,1,generator=rng)-1
    y0=7.5+2*torch.rand(n,1,1,generator=rng)-1
    rad=3.7+1.5*torch.rand(n,1,1,generator=rng)
    dx,dy=h[None]-x0,v[None]-y0
    mask=torch.where(torch.randint(2,(n,1,1),generator=rng)==0,dx**2+dy**2<=rad**2,(dx.abs()<=rad)&(dy.abs()<=rad))
    phase=2*torch.pi*torch.rand(n,1,1,generator=rng)
    noise=.015*torch.randn(n,6,3,16,16,generator=rng)
    axis=torch.where(y[:,None,None]==0,v[None],h[None])
    bit=torch.sin(axis*torch.pi/2+phase)>=0
    levels=torch.tensor(((38.2,38.2),(39.,37.3),(39.5,36.5),(40.,36.2),(40.2,36.),(41.1,35.8)))/50
    grating=torch.where(bit[:,None],levels[None,:,0,None,None],levels[None,:,1,None,None])
    gray=torch.where(mask[:,None],grating,torch.tensor(35.5/50))
    pixels=(gray[:,:,None].expand(-1,-1,3,-1,-1)+noise).clamp(0,1)
    return pixels,y,{'mask':mask,'phase':phase,'noise':noise}

@torch.no_grad()
def feats(model,pixels):
    shape=pixels.shape[:-3]
    hidden=model.net[:-1](pixels.reshape(-1,3,16,16)).reshape(*shape,64)
    logits=model.net[-1](hidden)
    probs=torch.cat((logits[...,:4].softmax(-1),logits[...,4:].softmax(-1)),-1)
    c,s=probs[...,:4],probs[...,4:]
    confident=torch.stack((c.max(-1).values,s.max(-1).values,-(c*c.clamp_min(1e-30).log()).sum(-1),-(s*s.clamp_min(1e-30).log()).sum(-1)),-1)
    edge=((pixels[..., :,1:]-pixels[..., :,:-1]).square().mean((-3,-2,-1))-(pixels[..., 1:,:]-pixels[..., :-1,:]).square().mean((-3,-2,-1)))[...,None]
    return dict(visual_hidden=hidden,visual_logits=logits,category_probabilities=probs,category_confidence=confident,physical_directional_edge=edge)

def readout(x,labels):
    x=x[:,-1].double();mu=x.mean(0);sd=(x-mu).square().mean(0).sqrt();sd=torch.where(sd>0,sd,torch.ones_like(sd));z=(x-mu)/sd
    target=2*labels.double()-1;b=target.mean()
    w=torch.linalg.solve(z.T@z/len(z)+.01*torch.eye(z.shape[-1],dtype=torch.float64),z.T@(target-b)/len(z))
    return dict(mean=mu,scale=sd,weights=w,intercept=b)
def scores(r,x):return ((x.double()-r['mean'])/r['scale'])@r['weights']+r['intercept']
def logistic(score,labels):
    margin=score.abs().double().flatten();target=((score>0).long()==labels[:,None]).double().flatten();mu=margin.mean();sd=margin.std(unbiased=False)
    if float(sd)==0:sd=torch.ones_like(sd)
    x=torch.stack((torch.ones_like(margin),(margin-mu)/sd),1);b=torch.zeros(2,dtype=torch.float64);pen=.001*torch.eye(2,dtype=torch.float64)
    for _ in range(100):
        p=(x@b).sigmoid();g=x.T@(p-target)/len(x)+pen@b;h=x.T@((p*(1-p))[:,None]*x)/len(x)+pen;b=b-torch.linalg.solve(h,g)
    residual=x.T@((x@b).sigmoid()-target)/len(x)+pen@b
    return dict(mean=mu,scale=sd,beta=b,baseline=target.mean(),gradient_max=residual.abs().max(),objective=(torch.nn.functional.softplus(x@b)-target*(x@b)).mean()+.001/2*b.square().sum())
def prob(cal,x):return (cal['beta'][0]+cal['beta'][1]*(x.abs().double()-cal['mean'])/cal['scale']).sigmoid()
def metric(p,y):
    p,y=p.flatten().double(),y.flatten().double();b=torch.bucketize(p,torch.tensor([.2,.4,.6,.8],dtype=torch.float64),right=True);rows=[];ece=0.
    for i in range(5):
        keep=b==i;n=int(keep.sum());mean=float(p[keep].mean()) if n else None;acc=float(y[keep].mean()) if n else None
        if n:ece+=n/len(p)*abs(mean-acc)
        rows.append(dict(bin=i,count=n,mean_probability=mean,accuracy=acc))
    return dict(accuracy=float(y.mean()),brier=float((p-y).square().mean()),ece=ece,reliability=rows)

def audit():
    torch.set_num_threads(2)
    manifest=json.loads((ROOT/'manifest.json').read_text());completion=json.loads((ROOT/'completion.json').read_text());result=json.loads((ROOT/'results.json').read_text());summary={}
    for path,expected in {**manifest['source_sha256'],**manifest['checkpoint_sha256']}.items():assert sha(path)==expected,path
    snapshots=json.loads((ROOT/'source_snapshots.json').read_text())
    for path,source in snapshots.items():assert hashlib.sha256(source.encode()).hexdigest()==manifest['source_sha256'][path]
    assert sha(ROOT/'results.json')==completion['results_sha256']
    for filename,expected in completion['archive_sha256'].items():assert sha(ROOT/filename)==expected,filename
    for seed in (1301,1311,1321):
        with gzip.open(ROOT/f'states-{seed}.pt.gz','rb') as f:saved=torch.load(f,weights_only=True)
        splits=[images(910000000+seed+10000*i,n) for i,n in enumerate((256,256,512))]
        same(saved['splits'],splits,f'{seed}/splits')
        assert all(int(s[1].sum())==len(s[1])//2 for s in splits)
        assert all(not torch.equal(s[2]['noise'][:,0],s[2]['noise'][:,1]) for s in splits)
        model=VisualEncoder().eval();model.load_state_dict(torch.load(f'audits/bound_content/confirmation_v2/seed{seed}.pt',weights_only=True)['state_dict'])
        features=[feats(model,s[0]) for s in splits];same(saved['features'],features,f'{seed}/features')
        # A current input must not acquire information from another batch member.
        sample=splits[2][0][torch.tensor([0,17,250]),torch.tensor([0,3,5])]
        batched=feats(model,sample);alone=[feats(model,p[None]) for p in sample];batch_diff={}
        for key in batched:
            independent=torch.cat([x[key] for x in alone]);diff=float((independent-batched[key]).abs().max());batch_diff[key]=diff;assert torch.allclose(independent,batched[key],atol=1e-4,rtol=1e-6),(seed,key,diff)
        idx=torch.randint(512,(256,512),generator=torch.Generator().manual_seed(920000000+seed));same(saved['bootstrap_indices'],idx,f'{seed}/bootstrap')
        null=splits[2][0][:,0,None].expand(-1,2,-1,-1,-1).clone();nullfeat=feats(model,null)
        same(saved['null_patches'],null,f'{seed}/nullimages');same(saved['null_features'],nullfeat,f'{seed}/nullfeatures')
        assessments={};prevalence={}
        for key in features[0]:
            r=readout(features[0][key],splits[0][1]);sc=[scores(r,x[key]) for x in features];cal=logistic(sc[1],splits[1][1]);p=prob(cal,sc[2]);y=((sc[2]>0).long()==splits[2][1][:,None]).double();ns=scores(r,nullfeat[key])
            same(saved['instruments'][key],dict(readout=r,calibrator=cal,scores=sc,probabilities=p,correct=y,null_scores=ns),f'{seed}/{key}/instrument')
            assert torch.equal(ns[:,0],ns[:,1]);assert torch.equal(nullfeat[key][:,0],nullfeat[key][:,1])
            a=metric(p,y);a['by_contrast']=[metric(p[:,i],y[:,i]) for i in range(6)];a['calibration_mean_baseline']=float(cal['baseline']);a['baseline_brier']=float((cal['baseline']-y).square().mean());a['accuracy_bootstrap_95_by_contrast']=torch.quantile(y[idx].mean(1),torch.tensor([.025,.975],dtype=torch.float64),dim=0).T.tolist()
            difference=((p-y).square()-(cal['baseline']-y).square()).mean(1);a['brier_difference_bootstrap_95']=torch.quantile(difference[idx].mean(1),torch.tensor([.025,.975],dtype=torch.float64)).tolist();a['duplicate_zero_accuracy']=float(((ns>0).long()==torch.arange(2)[None]).double().mean());assessments[key]=a
            cal_y=((sc[1]>0).long()==splits[1][1][:,None]).double();prevalence[key]={'calibration_by_contrast':cal_y.mean(0).tolist(),'evaluation_by_contrast':y.mean(0).tolist(),'calibration_pooled':float(cal_y.mean()),'evaluation_pooled':float(y.mean())}
            same(result['models'][str(seed)]['sources'][key],a,f'{seed}/{key}/results')
        hidden=assessments['visual_hidden'];physical=assessments['physical_directional_edge']
        gates=dict(hidden_high_contrast=hidden['by_contrast'][-1]['accuracy']>=.90,physical_high_contrast=physical['by_contrast'][-1]['accuracy']>=.90,hidden_zero_gross_chance=abs(hidden['by_contrast'][0]['accuracy']-.5)<=.075,physical_zero_gross_chance=abs(physical['by_contrast'][0]['accuracy']-.5)<=.075,all_duplicate_null_chance=all(a['duplicate_zero_accuracy']==.5 for a in assessments.values()),hidden_pooled_ece=hidden['ece']<=.10,hidden_brier_vs_calibration_baseline=hidden['brier']<=hidden['baseline_brier'])
        same(result['models'][str(seed)]['gates'],gates,f'{seed}/gates');assert result['models'][str(seed)]['engineering_gates_pass']==all(gates.values())
        summary[str(seed)]={'gates':gates,'feature_batch_invariance_max_absolute_difference':batch_diff,'feature_batch_invariance_absolute_tolerance':1e-4,'feature_batch_invariance_relative_tolerance':1e-6,'outcome_prevalence':prevalence,'hidden_conditional_ece':[a['ece'] for a in hidden['by_contrast']],'hidden_conditional_brier':[a['brier'] for a in hidden['by_contrast']]}
    assert result['all_engineering_gates_pass']==all(all(x['gates'].values()) for x in summary.values())
    assert result['goal_achieved']==False and result['attention_source_tested']==False and result['participant_rows_tested']==0 and result['new_reports']==0
    return {'audit':'independent isolated task reconstruction','max_reconstruction_absolute_difference':max(MAX_DIFF.values()),'tensor_absolute_tolerance':1e-12,'tensor_relative_tolerance':1e-12,'supplemental_check_erratum':'First audit launch stopped at a supplemental, nonregistered absolute feature batching tolerance 1e-5: seed1301 hidden discrepancy 1.52587890625e-5. Float32 batching variation is assessed with disclosed atol1e-4/rtol1e-6 on this second audit launch. No archived evidence or scientific gate changed.','models':summary,'all_checks_pass':True,'input_manifest_sha256':sha(ROOT/'manifest.json'),'input_completion_sha256':sha(ROOT/'completion.json'),'audit_script_sha256':sha(__file__),'audit_script_source':Path(__file__).read_text(),'human_review':False,'provenance':'Separate subagent, unblinded post-output audit; shares model family and commissioning context with parent. Not independent human or empirical appearance validation.'}
if __name__=='__main__':
    data=audit();Path('/tmp/isolated_orientation_audit_result.json').write_text(json.dumps(data,indent=2)+'\n');print(json.dumps({k:v for k,v in data.items() if k not in ('audit_script_source','models')},indent=2));print(json.dumps(data['models'],indent=2))
